<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { api, errorMessage, localTime } from './api'
import { personalGroups, employmentFields, blankPersonal, displayValue } from './employee-fields'
const props=defineProps({record:Object});const emit=defineEmits(['saved'])
const form=reactive({phone:'',location:'',timezone:'UTC',personal:blankPersonal(),expected_revision:0}), busy=ref(false),error=ref(''),message=ref('')
const completion=computed(()=>{const values=[form.phone,...Object.values(form.personal)];return Math.round(values.filter(v=>v!=='' && v!=null).length/values.length*100)})
function hydrate(record=props.record){if(!record)return;Object.assign(form,{phone:record.phone||'',location:record.location||'',timezone:record.timezone||'UTC',personal:{...blankPersonal(),...record.personal},expected_revision:record.revision||0});error.value='';message.value=''}
watch(()=>props.record?.email,()=>hydrate(),{immediate:true})
async function reload(){busy.value=true;error.value='';try{const {data}=await api.get('/local/portal',{params:{timezone:form.timezone}});hydrate(data.profile);emit('saved')}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';message.value='';try{await api.post('/local/profile',form);form.expected_revision++;message.value='Personal details saved. Your record is ready for HR review.';emit('saved')}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
</script>
<template><div v-if="record" class="personnel-layout"><aside class="card personnel-summary"><div class="employee-avatar large">{{record.name.slice(0,1).toUpperCase()}}</div><h2>{{record.name}}</h2><p class="muted">{{record.email}}</p><span class="pill" :class="record.reviewed_at?'green':'amber'">{{record.reviewed_at?'Reviewed by HR':'Awaiting HR review'}}</span><p v-if="record.reviewed_at" class="small muted">Reviewed {{localTime(record.reviewed_at)}}</p><div class="personnel-completion"><strong>{{completion}}%</strong><span> optional details filled</span><div class="employee-time-track"><div :style="{width:completion+'%'}"></div></div></div><p class="employee-caption">Keep your contact and emergency details current. HR review is a record check, not identity verification. No ID documents or government ID numbers are collected here.</p><button class="small-button" :disabled="busy" @click="reload">Reload saved details</button></aside><div><form @submit.prevent="save"><section class="card"><h2>Contact & preferences</h2><p class="muted small">Account name and work email are managed by your administrator.</p><div class="form-grid"><label>Phone number<input v-model.trim="form.phone" type="tel" maxlength="40" autocomplete="tel"></label><label>Work location<input v-model.trim="form.location" maxlength="120"></label><label>Reporting timezone<input v-model.trim="form.timezone" required maxlength="80" placeholder="Asia/Kolkata"></label></div></section><section v-for="group in personalGroups" :key="group.title" class="card"><h2>{{group.title}}</h2><div class="form-grid"><label v-for="field in group.fields" :key="field[0]" :class="{'personnel-wide':field[2]==='textarea'}">{{field[1]}}<textarea v-if="field[2]==='textarea'" v-model.trim="form.personal[field[0]]" rows="3" :maxlength="field[0]==='skills'?2000:field[0]==='permanent_address'?1500:1000"></textarea><input v-else v-model="form.personal[field[0]]" :type="field[2] || 'text'" :maxlength="field[0]==='personal_email'?255:field[0]==='institution'?200:120" :min="field[2]==='number'?1900:undefined" :max="field[2]==='number'?new Date().getFullYear()+10:undefined"></label></div></section><section class="card personnel-save"><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="message" class="notice success" role="status">{{message}}</p><p class="small muted">These personal fields are optional. Saving changes returns your record to HR for review.</p><button class="primary" :disabled="busy">{{busy?'Saving…':'Save personal details'}}</button></section></form><section class="card"><div class="card-heading"><div><h2>Employment information</h2><small>Maintained by your administrator</small></div><span class="pill neutral">Read only</span></div><dl class="personnel-facts"><div v-for="field in employmentFields" :key="field[0]"><dt>{{field[1]}}</dt><dd>{{displayValue(record.employment?.[field[0]])}}</dd></div></dl></section></div></div><div v-else class="card">Your profile will appear when the server is available.</div></template>
